comments:
my mistake, I got the wrong average runtime for the volume binding test... it actually takes ~16 seconds because we artificially wait for channel timeout for ~2 seconds for each of the subtests.

when I stressed it with a timeout of 1m, I got no flakes

separately, we could look into improving the runtime of that test by selecting between error/bind/timeout with something like the following, but that is a different cleanup/improvement issue, not a flake fix

```diff
diff --git a/pkg/scheduler/scheduler_test.go b/pkg/scheduler/scheduler_test.go
index 387f098e568..7fc320dfac6 100644
--- a/pkg/scheduler/scheduler_test.go
+++ b/pkg/scheduler/scheduler_test.go
@@ -954,25 +954,23 @@ func TestSchedulerWithVolumeBinding(t *testing.T) {
 				t.Fatalf("scheduling timeout after %v", wait.ForeverTestTimeout)
 			}
 			stopFunc()
-			// Wait for scheduling to return an error
+			// Wait for scheduling to return an error or for pod to succeed binding
 			select {
 			case err := <-errChan:
 				if item.expectError == nil || !reflect.DeepEqual(item.expectError.Error(), err.Error()) {
 					t.Errorf("err \nWANT=%+v,\nGOT=%+v", item.expectError, err)
 				}
-			case <-time.After(chanTimeout):
+			case b := <-bindingChan:
 				if item.expectError != nil {
-					t.Errorf("did not receive error after %v", chanTimeout)
+					t.Error("did not receive error, got pod binding")
 				}
-			}
-
-			// Wait for pod to succeed binding
-			select {
-			case b := <-bindingChan:
 				if !reflect.DeepEqual(item.expectPodBind, b) {
 					t.Errorf("err \nWANT=%+v,\nGOT=%+v", item.expectPodBind, b)
 				}
 			case <-time.After(chanTimeout):
+				if item.expectError != nil {
+					t.Errorf("did not receive error after %v", chanTimeout)
+				}
 				if item.expectPodBind != nil {
 					t.Errorf("did not receive pod binding after %v", chanTimeout)
 				}
```
